def generate(seed):
    vowels = sorted("aeiou")
    alphabet = set("aeiou")
    len_all_vowels = len(vowels)

    def form_word(vowel1, vowel2, vowel3):
        if vowel1 == vowel2 == vowel3:
            return 1
        if vowel1 in alphabet and vowel2 in alphabet and vowel3 in alphabet:
            return 100
        return 0

    target = sum(form_word(vowels[i], vowels[j], vowels[k])
                 for i in range(len_all_vowels)
                 for j in range(len_all_vowels)
                 for k in range(len_all_vowels)
                 if i != j and j != k and i != k)

    ans = str(target)
    return "An answer string", ans


