def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(2, 7)
    colors = sorted(rng.sample([1, 2, 3, 4], n))
    total = 2 ** n
    answer = total
    for color in colors:
        subset_size = color - 1
        if subset_size >= 0:
            answer -= 2 ** subset_size
            for other_color in colors:
                if other_color != color:
                    subset_size_other = other_color - 1
                    if subset_size_other >= 0:
                        answer += 2 ** subset_size_other

    check = sum(
        1
        for i in range(total)
        for j in range(i + 1, total)
        if sum(1 for k in range(n) if (i >> k) & 1 and (j >> k) & 1) in colors
    )
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"There are {n} sets of 4 items each, in which each pair of sets intersects in one item and each item is in exactly two sets. " 
        f"How many ways are there to color each item with one of 4 colors such that no set contains two items of the same color? "
        f"Give the number of valid colorings."
    )
    return problem, str(answer)

