def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)           # free parameter; widen freely
    s = rng.randint(15, 40)         # s in {15, 16, ..., 40}
    k = rng.randint(1, 5)           # k >= 1 keeps every factor positive

    assert s >= 3 * k and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    max_product = ((s + 3 * k) // 3) ** n    # = ((s + 3k)/3)^n, exact since s is a multiple of 3

    # Independent route: search every positive integer n-gon with sum of sides equal to s.
    # Since n | s, the real optimum is a regular n-gon with sides of length s/n, so
    # the searched maximum must equal the formula.
    check = max(
        ((a + k) * (n - 2) + (b + k) * (n - 2)) ** n
        for a in range(1, s - (n - 2))
        for b in range(1, s - (n - 2) - a)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a_1, a_2, ..., a_n be positive real numbers with a_1 + a_2 + ... + a_n = {s}. "
        f"What is the maximum value of (a_1 + {k}) * (a_2 + {k}) * ... * (a_n + {k})?"
    )

    return problem, str(max_product)

