    # Here, the objects are points, lines, circles, and figures, and the load-bearing structure is distance, angle, area, or incidence among them.
    lines = [(rng.randint(0, w), rng.randint(0, h), rng.randint(0, w), rng.randint(0, h)) for _ in range(3)]
    intersection1 = set()
    intersection2 = set()
    intersection3 = set()
    intersection_all = set()

    for line1 in lines:
        for line2 in lines:
            if line1[0] == line2[0] and line1[1] == line2[1]:
                intersection1.add((line1[0], line1[1]))
                break

    for line1 in lines:
        for line2 in lines:
            if line1[2] == line2[2] and line1[3] == line2[3]:
                intersection2.add((line1[2], line1[3]))
                break

    for line1 in lines:
        for line2 in lines:
            if line1[0] == line2[2] and line1[1] == line2[3]:
                intersection3.add((line1[0], line1[1]))
                break

    for line1 in lines:
        for line2 in lines:
            for line3 in lines:
                if line1[0] == line2[2] and line1[1] == line2[3] and line2[0] == line3[2] and line2[1] == line3[3]:
                    intersection_all.add((line1[0], line1[1]))
