    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many points (x, y) with 0 <= x <= {w} and 0 <= y <= {h} are not on any of the lines A, B, and C? State only the integer.\n"
        f"Line A: ({lines[0][0]}, {lines[0][1]}), ({lines[0][2]}, {lines[0][3]})\n"
