    # The real optimum is a = b = c = 10/3, so the answer ((a + k) + (b + k) + (c + k))^2
    # is an integer exactly when 3 | (a + b + c). Keep the invariant in the construction (3 * m), never in a value list.
    m = rng.randint(3, 7)          # free parameter; widen freely
    s = 3 * m                       # s in {9, 12, ..., 21}
    k = rng.randint(1, 4)           # k >= 1 keeps every factor positive

    assert s % 3 == 0 and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    max_sum = (m + k + m + k + m + k) ** 2      # = ((a + k) + (b + k) + (c + k))^2, exact since s = 3m

    # Independent route: search every non-negative integer tuple summing to s.
