        (a + k + b + k + c + k) ** 2
        for a in range(0, s + 1)
        for b in range(0, s - a + 1)
        for c in range(0, s - a - b + 1)
    )
    assert max_sum == check, f"max_sum={max_sum} check={check}"

    problem = (
        f"Let a, b, c be non-negative integers with a + b + c = {s}. "
