        if n % i == 0:
            if i % math.isqrt(i) != 0:
                check += 2
            else:
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many divisors of {n} are not perfect squares? State only the integer."
    )

    return problem, str(answer)

