def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 20)        # free parameter; widen freely
    gcd = rng.randint(1, 4)        # gcd in {1, 2, 3, 4}
    k = rng.randint(1, 5)          # k >= 1 keeps every factor positive

    # INVARIANT: the gcd must remain the same. The real optimum is when the
    # integers are distinct multiples of the gcd, so the answer ((a * gcd + k) * ...)
    # is an integer exactly when gcd divides the coefficients.
    # Keep the invariant in the construction (gcd * m), never in a value list.
    m = rng.randint(2, 5)          # free parameter; widen freely
    a = gcd * m                    # a in {2*gcd, 3*gcd, ..., 5*gcd}
    b = a + gcd                    # b in {3*gcd, 4*gcd, ..., 6*gcd}
    c = b + gcd                    # c in {4*gcd, 5*gcd, ..., 7*gcd}

    assert gcd == math.gcd(a, b, c) and k >= 1, (
        "invariant violated: gcd must remain the same and k >= 1"
    )

    max_product = (a + k) * (b + k) * (c + k)  # = ((a * gcd + k) * ...)
    assert (a + k) % gcd == 0 and (b + k) % gcd == 0 and (c + k) % gcd == 0, "gcd must divide the coefficients"

    # Independent route: search every triplet of distinct integers with the given gcd.
    # Since the gcd is the real optimum, the searched maximum must equal the formula.
    check = max(
        (x + k) * (y + k) * (z + k)
        for x in range(gcd, n * gcd, gcd)
        for y in range(x + gcd, n * gcd, gcd)
        for z in range(y + gcd, n * gcd, gcd)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c be distinct positive integers with gcd(a, b, c) = {gcd}. "
        f"What is the maximum value of (a + {k})(b + {k})(c + {k})?"
    )

    return problem, str(max_product)

