def is_lattice_point_inside_polygon(x, y, vertices):
    n = len(vertices)
    inside = False
    p1x, p1y = vertices[0]
    for i in range(1, n + 1):
        p2x, p2y = vertices[i % n]
        if (y > min(p1y, p2y)):
            if (y <= max(p1y, p2y)):
                if (x <= max(p1x, p2x)):
                    if (p1y != p2y):
                        xints = (y - p1y) * (p2x - p1x) / (p2y - p1y) + p1x
                    if (p1x == p2x or x <= xints):
                        inside = not inside
        p1x, p1y = p2x, p2y
    return inside

