def count_combinations(max_value, n):
    # Generate all possible combinations of numbers from 1 to max_value that sum to n
    def backtrack(start, current_sum, current_combination):
        if current_sum == n:
            return 1
        count = 0
        for i in range(start, max_value + 1):
            if current_sum + i <= n:
                count += backtrack(i, current_sum + i, current_combination + [i])
        return count

    return backtrack(1, 0, [])

