    edge_matrix = [[0] * faces for _ in range(faces)]
    edge_index = 0
    for i in range(faces):
        for j in range(i + 1, faces):
            edge_matrix[i][j] = edge_matrix[j][i] = edge_counts[edge_index]
            edge_index += 1

    # Calculate the number of edges that form a cycle between each pair of faces
    cycles = {i: [] for i in range(faces)}
    for i in range(faces):
        for j in range(i + 1, faces):
            if edge_matrix[i][j] == 1:
                cycles[i].append(j)
