    share_edge_with_both = {i: 0 for i in range(faces)}
    for i in range(faces):
        for j in cycles[i]:
            for k in cycles[j]:
                if k != i and k != j:
                    share_edge_with_both[i] += 1

    # Calculate the number of faces that share an edge with all three others
    share_edge_with_all_three = {i: 0 for i in range(faces)}
    for i in range(faces):
