def count_triangles(n, avoid):
    # Count total number of triangles with side lengths <= n
    total = 0
    for a in range(1, n + 1):
        for b in range(a, n + 1):
            for c in range(b, n + 1):
                if a + b > c and a + c > b and b + c > a:
                    total += 1

    # Subtract triangles that include at least one of the avoided sides
    for length in avoid:
        for a in range(1, n + 1):
            for b in range(a, n + 1):
                for c in range(b, n + 1):
                    if a == length or b == length or c == length:
                        if a + b > c and a + c > b and b + c > a:
                            total -= 1

    # Add back triangles that include exactly two of the avoided sides (by
    # inclusion-exclusion)
    for length in avoid:
        for a in range(1, n + 1):
            for b in range(a, n + 1):
                for c in range(b, n + 1):
                    if a == length and b == length or a == length and c == length or b == length and c == length:
                        if a + b > c and a + c > b and b + c > a:
                            total += 1

    return total

