def max_ind_set(graph):
    independent_set = []
    visited = set()

    for v in sorted(graph, reverse=True):
        if v not in visited:
            independent_set.append(v)
            for neighbor in sorted(graph[v]):
                if neighbor not in visited:
                    visited.add(neighbor)

    return len(independent_set)

