def count_subsets(target, min_subset_size, max_subset_size):
    ways = [[0] * (target + 1) for _ in range(max_subset_size + 1)]
    for i in range(target + 1):
        ways[0][i] = 1 if i == 0 else 0

    for subset_size in range(1, max_subset_size + 1):
        for target_sum in range(target + 1):
            if target_sum < subset_size:
                ways[subset_size][target_sum] = ways[subset_size - 1][target_sum]
            else:
                ways[subset_size][target_sum] = ways[subset_size - 1][target_sum]
                for i in range(1, target_sum - subset_size + 1):
                    ways[subset_size][target_sum] += ways[subset_size - 1][target_sum - i]

    return ways[subset_size][target_sum]

