def generate(seed):
    rng = random.Random(seed)
    n = 3
    options = [(2, 2), (2, 3), (3, 3)]
    nrc = lambda x, y: rng.randint(x, y)

    def tangle():
        t1, t2 = options
        if len(options) > 0:
            t1, t2 = random.choice(options)
        t2 = nrc(t1 * 3, n * n * 2) % n
        options = [(x, y) for x, y in options if x != t1 or y != t2]
        return (t1, t2)

    def bi(t):
        if t < 3: return (t + 3, n)
        if t < 6: return (3, t % 3)
        return (n - 3 + t % 6, n + t % 6)

    output = []
    while len(options) > 0:
        i1, i2 = tangle()
        output.append((i1, i2))
        x, y = bi(i1 * i2)
        output.append((x, y))
        z = nrc(1, n - 1)
        output.append((z, n + z))

    answer = len(output) // 3
    check = sum(output) // 3
    assert answer == check, f"answer={answer} check={check}"

