    dp[0] = 0
    for sum_val in range(1, target + 1):
        for pair_sum in range(min_pair_sum, max_pair_sum + 1):
            if sum_val >= pair_sum:
                dp[sum_val] = max(dp[sum_val], dp[sum_val - pair_sum] + 1)
