def count_distinct_triangles(target, min_length, max_length):
    counts = {i: 0 for i in range(min_length, max_length + 1)}
    for length in range(min_length, max_length + 1):
        if length > target:
            continue
        counts[length] += 1

    distinct_triangles = set()
    for length in range(min_length, max_length + 1):
        if length > target:
            continue
        for count in range(1, counts[length] + 1):
            if length * count > target:
                break
            remaining = target - length * count
            if remaining == 0:
                distinct_triangles.add((count,))
                break
            if remaining < min_length:
                continue
            for sub_count in range(1, counts[remaining] + 1):
                if remaining * sub_count + length * count == target:
                    distinct_triangles.add((count, sub_count))

    return len(distinct_triangles)

