def find_max_selection(n, min_sum, max_sum):
    if n < min_sum:
        return -1

    # Generate all possible subsets
    all_subsets = []
    for r in range(1, min(max_sum, n // min_sum) + 1):
        for subset in combinations(range(1, n + 1), r):
            if is_valid_subset(subset, n, min_sum, max_sum):
                all_subsets.append(subset)

    # Use set to remove duplicates
    unique_subsets = set(all_subsets)

