def find_prime_factors(n):
    factors = {}
    for i in range(2, int(math.sqrt(n)) + 1):
        while n % i == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
    if n > 1:
        factors[n] = 1
    return factors


def count_divisors(n):
    factors = find_prime_factors(n)
    if not factors:
        return 1
    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count


