    # Independent route: manually count divisors by checking all numbers up to sqrt(n)
    check = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            check += 1
            if i != n // i:
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many strictly positive integers are divisors of the number {n}? State only the integer."
    )
    return problem, str(answer)

