    max_exp = rng.randint(20, 40)
    n = rng.randint(50, 100)

    # Generate the set of possible exponents
    exponents = list(range(min_exp, max_exp + 1))

    # Function to count the number of valid subsets using dynamic programming
    def count_valid_subsets_dp(exponents, target):
        dp = [[0] * (target + 1) for _ in range(len(exponents) + 1)]

        for i in range(len(exponents) + 1):
            dp[i][0] = 1

        for i in range(1, len(exponents) + 1):
            for j in range(1, target + 1):
                if exponents[i - 1] <= j:
                    dp[i][j] = dp[i - 1][j] + dp[i - 1][j - exponents[i - 1]]
                else:
                    dp[i][j] = dp[i - 1][j]

        return dp[len(exponents)][target]

    # Find the number of valid subsets using dynamic programming
    answer = count_valid_subsets_dp(sorted(exponents), n)

    # Independent route: count the number of subsets using recursion
    def count_valid_subsets_rec(exponents, target):
        if target == 0:
            return 1

        if target < 0 or not exponents:
            return 0

        return (count_valid_subsets_rec(exponents, target - exponents[0]) +
                count_valid_subsets_rec(exponents[1:], target))

    check = count_valid_subsets_rec(sorted(exponents), n)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of distinct powers of 2 where the exponent ranges from {min_exp} to {max_exp} (inclusive). "
