def count_valid_subsets(n, min_subset_sum, max_subset_sum, target_value):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(current_sum, num_elements_used):
        if num_elements_used > n:
            return 0
        if current_sum == target_value:
            return 1
        if num_elements_used == n or current_sum > target_value:
            return 0

        count = 0
        for element in range(1, n + 1):
            if element not in used_elements:
                if min_subset_sum <= current_sum + element <= max_subset_sum:
                    used_elements.add(element)
                    count += dp(current_sum + element, num_elements_used + 1)
                    used_elements.remove(element)
        return count

    used_elements = set()
    return dp(0, 0)


