def find_max_exponent(n, min_exp, max_exp):
    if n < min_exp:
        return 0

    if min_exp == max_exp:
        return 1 if n == min_exp else 0

    # Use dynamic programming to avoid recursion
    dp = [0] * (n + 1)
    dp[0] = 0

    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            if remaining_n >= min_exp:
                dp[remaining_n] = 1 + dp[min_exp]
            if exponent <= n:
                dp[exponent] = 1 + dp[exponent - 1]

    return dp[n] if n < max_exp + 1 else 0


