def find_combinations(n, min_size, max_size):
    valid_sizes = list(range(min_size, max_size + 1))

    def is_valid_combination(comb):
        return sum(comb) == n and all(subset_size <= n for subset_size in comb)

    all_combinations = []
    for r in range(1, len(valid_sizes) + 1):
        for comb in combinations(valid_sizes, r):
            if is_valid_combination(comb):
                all_combinations.append(comb)

    return all_combinations

