    )

    return problem, str(answer)


def fibonacci(k):
    if k == 1 or k == 2:
        return 1
    else:
        a, b = 1, 1
        for _ in range(k - 2):
            a, b = b, a + b
        return b


def is_fibonacci(num):
    a, b = 0, 1
    while b < num:
        a, b = b, a + b
    return b == num

