import sympy

GROUP = "geometry"
SKILL = "transformation"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(30, 50)

    # Generate a random polygon with vertices on a grid
    vertices = [(x, y) for x in range(n) for y in range(n) if rng.randint(0, 10) < 2]
    sorted_vertices = sorted(vertices)

    # Find the number of triangles where the area is a prime number and their vertices are in prime positions
    def is_prime_area(points):
        # Calculate the area using the shoelace formula
        x, y = zip(*points)
        area = 0.5 * abs(sum(x[i] * y[(i + 1) % len(points)] - y[i] * x[(i + 1) % len(points)] for i in range(len(points))))
        return sympy.isprime(int(area))

    def is_prime_position(point, points):
        idx = points.index(point)
        return sympy.isprime(idx)

    answer = sum(1 for i in range(len(vertices)) for j in range(i + 1, len(vertices)) for k in range(j + 1, len(vertices))
                 if sympy.isprime(int(vertices[i][0])) and sympy.isprime(int(vertices[j][0])) and sympy.isprime(int(vertices[k][0]))
                 and is_prime_position(vertices[i], sorted_vertices) and is_prime_position(vertices[j], sorted_vertices) and is_prime_position(vertices[k], sorted_vertices)
                 and is_prime_area([vertices[i], vertices[j], vertices[k]]))

    # Independent route: Verify the count by explicitly checking each triplet for the conditions.
    check = 0
    for i in range(len(vertices)):
        for j in range(i + 1, len(vertices)):
            for k in range(j + 1, len(vertices)):
                if (sympy.isprime(int(vertices[i][0])) and sympy.isprime(int(vertices[j][0])) and sympy.isprime(int(vertices[k][0]))
                    and is_prime_position(vertices[i], sorted_vertices) and is_prime_position(vertices[j], sorted_vertices) and is_prime_position(vertices[k], sorted_vertices)
                    and is_prime_area([vertices[i], vertices[j], vertices[k]])):
                    check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many triangles can be formed with vertices from a grid of points where each point's x-coordinate is a prime number, and the positions of the vertices are also prime numbers? The triangles must have an area that is also a prime number.\n"
        f"The problem asks for the count of such triangles formed from vertices in a grid of points where each point's x-coordinate and position are prime numbers.\n"
        f"Vertices in the range are: {vertices}"
    )

    return problem, str(answer)

