    for i in range(num_circles):
        for j in range(i + 1, num_circles):
            if abs(circle_positions[i] - circle_positions[j]) <= radii[i] + radii[j]:
                answer += 1

    # Independent route: Verify the count by checking each pair of positions
    check = 0
    for i in range(num_circles):
        for j in range(i + 1, num_circles):
            if abs(circle_positions[i] - circle_positions[j]) <= radii[i] + radii[j]:
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many pairs of circles among the ones with radii {radii} and "
        f"centres at distances {circle_positions} along a line intersect? State only the integer.\n"
        f"The problem asks for the number of intersecting pairs where each distance is a unique position.\n"
        f"Radii: {radii}\n"
        f"Distances: {circle_positions}"
    )

    return problem, str(answer)
